//
//  DinoOfflinePage.swift
//  dino
//
//  Minimalist, zen offline error page with editorial tree layout matching the Dino theme.
//

import Foundation

enum DinoOfflinePage {
    /// Returns true if the error represents an offline, unreachable host, or network timeout condition.
    static func isOfflineError(_ error: Error) -> Bool {
        let nsError = error as NSError
        let offlineCodes: Set<Int> = [
            NSURLErrorNotConnectedToInternet,
            NSURLErrorCannotFindHost,
            NSURLErrorCannotConnectToHost,
            NSURLErrorNetworkConnectionLost,
            NSURLErrorDNSLookupFailed,
            NSURLErrorTimedOut,
            NSURLErrorResourceUnavailable,
            NSURLErrorCannotLoadFromNetwork
        ]
        if offlineCodes.contains(nsError.code) {
            return true
        }
        let desc = error.localizedDescription.lowercased()
        if desc.contains("offline") || desc.contains("internet connection") || desc.contains("server cannot be found") || desc.contains("network connection was lost") {
            return true
        }
        return false
    }

    /// Embedded high-resolution defringed pixel-art tree illustration.
    private static let treeImageBase64: String = ""

    /// Generates the self-contained offline page HTML for the requested URL.
    static func html(for url: URL, error: Error? = nil) -> String {
        let rawURL = url.absoluteString
        let safeURL = rawURL.replacingOccurrences(of: "\\", with: "\\\\").replacingOccurrences(of: "'", with: "\\'")
        
        return """
        <!DOCTYPE html>
        <html lang="en">
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>uh oh! your internets broken — Dino</title>
          <style>
            * {
              box-sizing: border-box;
              margin: 0;
              padding: 0;
            }
            body {
              font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
              background-color: #28292A;
              color: #E8EAED;
              display: flex;
              align-items: center;
              justify-content: center;
              min-height: 100vh;
              padding: 40px 32px;
              user-select: none;
              -webkit-user-select: none;
              overflow: hidden;
            }
            .stage {
              display: flex;
              flex-direction: row;
              align-items: center;
              justify-content: center;
              gap: 56px;
              max-width: 680px;
              width: 100%;
            }
            .tree-col {
              flex-shrink: 0;
              cursor: pointer;
            }
            .tree {
              width: 195px;
              height: auto;
              display: block;
              image-rendering: -webkit-optimize-contrast;
              image-rendering: pixelated;
              transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
              filter: drop-shadow(0 16px 32px rgba(0, 0, 0, 0.36));
            }
            .tree:hover {
              transform: scale(1.06) rotate(-1deg);
            }
            .tree:active {
              transform: scale(0.96);
            }
            .content-col {
              display: flex;
              flex-direction: column;
              align-items: flex-start;
              text-align: left;
            }
            h1 {
              font-size: 24px;
              font-weight: 600;
              letter-spacing: -0.02em;
              color: #E8EAED;
              margin-bottom: 8px;
              line-height: 1.25;
            }
            p.subtitle {
              font-size: 14px;
              font-weight: 400;
              color: #E8EAED;
              opacity: 0.50;
              margin-bottom: 10px;
            }
            p.grass {
              font-size: 13.5px;
              font-weight: 400;
              font-style: italic;
              color: #E8EAED;
              opacity: 0.38;
              margin-bottom: 24px;
            }
            .retry-btn {
              appearance: none;
              -webkit-appearance: none;
              background: rgba(255, 255, 255, 0.08);
              border: 1px solid rgba(255, 255, 255, 0.14);
              border-radius: 9999px;
              color: #E8EAED;
              font-size: 13px;
              font-weight: 500;
              padding: 8px 22px;
              cursor: pointer;
              outline: none;
              transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
            }
            .retry-btn:hover {
              background: rgba(255, 255, 255, 0.15);
              border-color: rgba(255, 255, 255, 0.24);
            }
            .retry-btn:active {
              transform: scale(0.96);
            }
            @media (max-width: 580px) {
              .stage {
                flex-direction: column;
                gap: 28px;
                text-align: center;
              }
              .content-col {
                align-items: center;
                text-align: center;
              }
              .tree {
                width: 150px;
              }
            }
          </style>
        </head>
        <body>
          <div class="stage">
            <div class="tree-col" onclick="retry()" title="Click to retry">
              <img class="tree" src="data:image/png;base64,\(treeImageBase64)" alt="Tree" />
            </div>
            <div class="content-col">
              <h1>uh oh! your internets broken</h1>
              <p class="subtitle">try restarting your wifi</p>
              <p class="grass">maybe it's high time you go touch some grass.</p>
              <button class="retry-btn" onclick="retry()">Try Again</button>
            </div>
          </div>

          <script>
            function retry() {
              var target = '\(safeURL)';
              if (target && target !== 'about:blank' && !target.startsWith('data:')) {
                window.location.href = target;
              } else {
                window.location.reload();
              }
            }
            window.addEventListener('keydown', function(e) {
              if (e.key === 'Enter' || e.key === ' ') {
                retry();
              }
            });
          </script>
        </body>
        </html>
        """
    }
}
